+// ---------------------------------------------------------------------------
+// Clone callback — called by tag_rules_clone() for each rule in the active list
+// ---------------------------------------------------------------------------
+
+static void
+tag_rule_add_cb(tag_rule_t *rule, void *user_data)
+{
+    TaggingRulesModel *model = static_cast<TaggingRulesModel *>(user_data);
+    if (model == NULL)
+        return;
+
+    model->addRule(rule);
