+
+TaggingRulesModel::TaggingRulesModel(QObject *parent)
+    : QAbstractItemModel(parent),
+      root_(new TaggingRuleItem(false, QString(), QString(), QString(), QString(), QString(), NULL))
+{
+    tag_rules_clone(tag_rule_add_cb, this);
+}
